import ast; from pathlib import Path
paths = sorted(Path("migrations").glob("*.py"))
print(f"Auditing SQL call arguments in {len(paths)} migrations")
for path in paths:
    tree = ast.parse(path.read_text(), filename=str(path))
    for node in ast.walk(tree):
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and node.func.attr in {"execute", "executemany", "executescript"}:
            query = node.args[0]
            if not isinstance(query, ast.Constant):
                print(f"{path}:{node.lineno}: {ast.unparse(query)}")
